    rules = list(current_app.url_map.iter_rules())

    if not rules:
        click.echo("No routes were registered.")
        return

    ignored_methods = set(()) if all_methods else ("HEAD", "OPTIONS")

    if domain:
        # Group by domain first, then apply the requested sort within each
        # domain. Rules without a host match any domain and are grouped
        # under the empty string.
        if sort in ("endpoint", "rule"):
            rules = sorted(rules, key=lambda r: (r.host, getattr(r, sort)))
        elif sort == "methods":
            rules = sorted(
                rules, key=lambda r: (r.host, sorted(r.methods))  # type: ignore
            )
        else:
            # Keep match order within each domain.
            rules = sorted(rules, key=lambda r: r.host)
    else:
        if sort in ("endpoint", "rule"):
            rules = sorted(rules, key=attrgetter(sort))
        elif sort == "methods":
            rules = sorted(
                rules, key=lambda r: sorted(r.methods)  # type: ignore
            )

    rule_methods = [
        ", ".join(sorted(rule.methods - ignored_methods)) for rule in rules
    ]

    if domain:
        headers = ("Domain", "Endpoint", "Methods", "Rule")
        details = [(rule.host, rule.endpoint, methods, rule.rule)
                   for rule, methods in zip(rules, rule_methods)]
