def iter_rules(self, domain: t.Optional[str] = None) -> t.Iterator[Rule]:
    """Return the registered rules grouped by their full domain, defined
    as the subdomain combined with :data:`SERVER_NAME`.

    Rules that do not set a subdomain are shown under the base server
    name, with the default subdomain (usually the empty string)
    applied. If :data:`SERVER_NAME` is not configured, a warning is
    shown and every rule's domain is the empty string.

    This is the same information used by the ``flask routes`` command
    to show which routes belong to which domain.

    .. versionadded:: 2.3
    """
    if self.config["SERVER_NAME"] is None:
        warnings.warn(
            "'SERVER_NAME' must be set in order for 'flask routes' to"
            " show domains. Set it to show domains, or filter within"
            " the app instead.",
            stacklevel=2,
        )
        return iter(self.url_map.iter_rules())

    server_name = self.config["SERVER_NAME"]
    default = self.url_map.default_subdomain

    if domain is not None:
        filtered = set(
            r
            for r in self.url_map.iter_rules()
            if ".".join(
                x for x in (r.subdomain or default, server_name) if x
            )
            == domain
        )
        return iter(sorted(filtered, key=lambda r: r.endpoint))

    return iter(
        sorted(
            self.url_map.iter_rules(),
            key=lambda r: (
                ".".join(x for x in (r.subdomain or default, server_name) if x),
                r.endpoint,
            ),
        )
    )

