def routes_command(sort: str, all_methods: bool) -> None:
    """Show all registered routes with endpoints and methods."""

    rules = list(current_app.url_map.iter_rules())
    if not rules:
        click.echo("No routes were registered.")
        return

    ignored_methods = set() if all_methods else {"HEAD", "OPTIONS"}

    if sort == "endpoint":
        rules = sorted(rules, key=attrgetter("endpoint"))
    elif sort == "rule":
        rules = sorted(rules, key=attrgetter("rule"))
    elif sort == "methods":
        rules = sorted(rules, key=lambda rule: sorted(rule.methods))

    show_domain = current_app.config["SERVER_NAME"] is not None

    def domain_of(rule: Rule) -> str:
        """Return the full domain a rule is registered for."""
        subdomain = rule.subdomain

        if subdomain == current_app.url_map.default_subdomain:
            # A rule with no subdomain falls back to the host, which is
            # only set when host matching is enabled.
            subdomain = rule.host

        if subdomain is None:
            subdomain = current_app.url_map.default_subdomain

        server_name = current_app.config["SERVER_NAME"]

        if server_name and subdomain:
            return f"{subdomain}.{server_name}"

        return subdomain or server_name or ""

    if show_domain:
        # Sort by the domain each rule matches, then by the existing order
        # within the domain. This is a stable sort so rules with the same
        # domain retain the order chosen above.
        rules = sorted(rules, key=domain_of)

    rule_methods = [
        ", ".join(sorted(rule.methods - ignored_methods)) for rule in rules
    ]

    if show_domain:
        headers = ("Domain", "Endpoint", "Methods", "Rule")
        rows = [
            (domain_of(rule), rule.endpoint, methods, rule.rule)
            for rule, methods in zip(rules, rule_methods)
        ]
    else:
        headers = ("Endpoint", "Methods", "Rule")
        rows = [
            (rule.endpoint, methods, rule.rule)
            for rule, methods in zip(rules, rule_methods)
        ]

