        max(len(headers[i]), *(len(row[i]) for row in rows))
        for i in range(len(headers))
    ]
    template = "  ".join(
        "{{{0}:<{{{1}}}}}".format(i, i + len(widths)) for i in range(len(widths))
    )

    click.echo(template.format(*headers, *widths).strip())
    click.echo(template.format(*("-" * width for width in widths), *widths))

    for row in rows:
        click.echo(template.format(*row, *widths).rstrip())

